.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds :is(code,pre) { font-family:var(--p-mono-font); }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-lg); height:var(--p-icon-lg); object-fit:contain; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:calc(var(--p-space-unit) * 5); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(0)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }
.ds .ds-admin-error { color:var(--p-error); font-size:var(--p-text-body); }

.ds .ds-button { display:inline-flex; justify-content:center; align-items:center; gap:var(--p-space-xs); min-width:var(--p-control-size-md); min-height:var(--p-control-size-md); padding:var(--p-space-xs) calc(var(--p-space-unit) * 5); border:var(--p-border-width) solid var(--p-accent); border-radius:var(--p-control-radius); background:var(--p-accent); color:var(--p-on-accent); font-size:var(--p-text-body); font-weight:var(--p-weight-semibold); line-height:var(--p-leading-snug); box-shadow:var(--p-control-shadow); text-decoration:none; transition:background var(--p-duration),box-shadow var(--p-duration); }
.ds .ds-button[data-variant="outline"] { border-color:var(--p-control-border); color:var(--p-ink); background:var(--p-surface); box-shadow:var(--p-raised); }
.ds .ds-button[data-variant="ghost"] { color:var(--p-ink); background:transparent; border-color:transparent; box-shadow:none; }
.ds .ds-button[data-size="sm"] { min-height:var(--p-control-size-sm); min-width:var(--p-control-size-sm); padding:var(--p-space-xs) var(--p-space-md); font-size:var(--p-text-sm); }
.ds .ds-button[data-size="lg"] { min-height:var(--p-control-size-lg); min-width:var(--p-control-size-lg); padding:var(--p-space-md) var(--p-space-lg); font-size:var(--p-text-md); }
.ds .ds-button:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-accent-shaded); }
.ds .ds-button[data-variant="outline"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-high); }
.ds .ds-button[data-variant="ghost"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-disabled); }
.ds .ds-button:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:var(--p-pressed); }
.ds .ds-button:not([data-variant="primary"]):not(:disabled):is(:active,[data-state="pressed"]) { background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-button[data-state="focus"] { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ds-button:disabled { opacity:var(--p-opacity-full); box-shadow:none; background:var(--p-disabled); border-color:var(--p-line); color:var(--p-muted); }
.ds .ds-button[aria-busy="true"] { background:var(--p-accent); color:var(--p-on-accent); border-color:var(--p-accent); }
.ds .ds-spinner { width:var(--p-size-md); height:var(--p-size-md); flex-shrink:0; border:var(--p-border-width-strong) solid currentColor; border-right-color:transparent; border-radius:var(--p-radius-circle); animation:ds-spin var(--p-duration-spin) var(--p-ease-linear) infinite; }
@keyframes ds-spin { to { transform:rotate(360deg); } }
@media(prefers-reduced-motion:reduce) { .ds .ds-spinner { border-style:var(--p-stroke-dotted); } }
/* looks: 채움(primary) · 윤곽(outline) · 글자(ghost) are the data-variant colour roles above */
.ds .ds-button-count { display:inline-grid; place-items:center; min-width:var(--p-size-lg); height:var(--p-size-lg); padding:0 var(--p-space-xs); border-radius:var(--p-radius-full); background:var(--p-accent); color:var(--p-on-accent); font-size:var(--p-text-sm); font-weight:var(--p-weight-bold); line-height:var(--p-leading-none); }
.ds .ds-button[data-variant="primary"] .ds-button-count { background:var(--p-on-accent); color:var(--p-accent); }

.ds .ds-field,.ds .ds-select-field { display:grid; gap:var(--p-space-xs); min-width:0; font-size:var(--p-text-body); }
.ds .ds-field > label,.ds .ds-select-field > span { font-weight:var(--p-weight-semibold); }
.ds .ds-help { font-size:var(--p-text-sm); color:var(--p-muted); line-height:var(--p-leading-normal); }
.ds .ds-field[data-state="error"] .ds-help { color:var(--p-error); }
.ds .ds-field[data-state="error"] .ds-help::before { content:'!'; display:inline-grid; place-items:center; width:var(--p-size-md); height:var(--p-size-md); font-size:var(--p-text-sm); border:var(--p-border-width) solid currentColor; border-radius:var(--p-radius-circle); margin-right:var(--p-space-2xs); }
.ds .ds-field[data-state="success"] .ds-help { color:var(--p-success); }
.ds .ds-field[data-state="success"] .ds-help::before { content:'✓'; margin-right:var(--p-space-2xs); }
.ds .ds-field[data-state="success"] .ds-input { border-color:var(--p-success); }
.ds .ds-field[data-state="focus"] .ds-input { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }

.ds .ds-input { display:block; width:100%; min-width:0; min-height:var(--p-control-size-md); padding:var(--p-space-sm) var(--p-space-md); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-control-radius); background:var(--p-bg); box-shadow:var(--p-inset); color:var(--p-ink); font-size:var(--p-text-body); line-height:var(--p-leading-normal); }
.ds select.ds-input { appearance:none; padding-inline-end:calc(var(--p-space-md) * 2 + var(--p-size-2xs)); background-image:linear-gradient(45deg,transparent calc(50% - var(--p-border-width)),var(--p-muted) calc(50% - var(--p-border-width)) calc(50% + var(--p-border-width)),transparent calc(50% + var(--p-border-width))),linear-gradient(-45deg,transparent calc(50% - var(--p-border-width)),var(--p-muted) calc(50% - var(--p-border-width)) calc(50% + var(--p-border-width)),transparent calc(50% + var(--p-border-width))); background-size:calc(var(--p-size-2xs) + var(--p-space-3xs)) calc(var(--p-size-2xs) + var(--p-space-3xs)); background-position:calc(100% - var(--p-space-md) - var(--p-size-2xs) - var(--p-space-3xs)) 50%,calc(100% - var(--p-space-md)) 50%; background-repeat:no-repeat; cursor:pointer; }
.ds select.ds-input:disabled { cursor:not-allowed; }
.ds .ds-input::placeholder { color:var(--p-muted); opacity:var(--p-opacity-full); }
.ds .ds-input:disabled { opacity:var(--p-opacity-full); box-shadow:none; color:var(--p-muted); background:var(--p-disabled); border-color:var(--p-line); cursor:not-allowed; }
.ds .ds-input[aria-invalid="true"] { border-color:var(--p-error); border-width:var(--p-border-width-strong); padding:var(--p-space-xs) var(--p-space-sm); }
.ds label.ds-field { display:grid; gap:var(--p-space-xs); min-width:0; font-size:var(--p-text-body); }
/* looks: 윤곽(box) is the base box; 채움(filled) keeps only a bottom rule on a tinted surface (Material 3 filled text field) */
.ds .ds-input[data-look="filled"] { border-width:0 0 var(--p-border-width-strong); border-radius:var(--p-control-radius) var(--p-control-radius) 0 0; background:var(--p-surface); box-shadow:none; }
.ds .ds-input[data-look="filled"][aria-invalid="true"] { padding:var(--p-space-sm) var(--p-space-md); }
.ds .ds-input[data-look]:disabled { background:var(--p-disabled); border-color:var(--p-line); color:var(--p-muted); box-shadow:none; }
.ds .ds-input[data-look][aria-invalid="true"] { border-color:var(--p-error); }

.ds .ds-choices { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,var(--p-space-unit) * 42),1fr)); gap:var(--p-space-lg); }
.ds .ds-choices fieldset,.ds .ds-radio-group { border:0; padding:0; min-width:0; }
.ds .ds-choices legend,.ds .ds-radio-group legend { font-size:var(--p-text-body); font-weight:var(--p-weight-semibold); margin-bottom:var(--p-space-sm); padding:0; }
.ds .ds-choice { display:flex; align-items:center; gap:var(--p-space-sm); min-height:var(--p-control-size-sm); width:fit-content; padding-inline:var(--p-space-2xs); cursor:pointer; font-size:var(--p-text-body); }
.ds .ds-choice input { appearance:none; position:relative; margin:0; width:var(--p-size-lg); height:var(--p-size-lg); border:var(--p-border-width-strong) solid var(--p-control-border); border-radius:var(--p-radius-md); background:var(--p-bg); box-shadow:var(--p-inset); cursor:inherit; flex-shrink:0; }
.ds .ds-choice input:checked,.ds .ds-choice input:indeterminate { background:var(--p-accent); border-color:var(--p-accent); box-shadow:none; }
.ds .ds-choice input[type="checkbox"]:checked::after { content:''; position:absolute; width:var(--p-size-xs); height:var(--p-size-sm); left:calc(50% - var(--p-size-2xs)); top:var(--p-space-3xs); border:solid var(--p-on-accent); border-width:0 var(--p-border-width-strong) var(--p-border-width-strong) 0; transform:rotate(45deg); }
.ds .ds-choice input:indeterminate::after { content:''; position:absolute; width:var(--p-size-sm); height:var(--p-border-width-strong); left:calc(50% - var(--p-size-sm) / 2); top:calc(50% - var(--p-border-width-strong) / 2); background:var(--p-on-accent); transform:none; border:0; }
.ds .ds-choice input[type="radio"] { border-radius:var(--p-radius-circle); }
.ds .ds-choice input[type="radio"]:checked::after { content:''; position:absolute; inset:var(--p-space-2xs); background:var(--p-on-accent); border-radius:var(--p-radius-circle); }
.ds .ds-choice:has(:disabled) { color:var(--p-muted); cursor:not-allowed; }
.ds .ds-choice input:disabled { opacity:var(--p-opacity-full); background:var(--p-disabled); border-color:var(--p-line); box-shadow:none; }
.ds .ds-choice input:disabled::after { border-color:var(--p-muted); }
.ds .ds-choice input[type="radio"]:disabled::after { background:var(--p-muted); }
.ds .ds-choice .ds-switch { width:var(--p-control-size-sm); height:var(--p-size-lg); border-radius:var(--p-radius-2xl); }
.ds .ds-switch::before { content:''; position:absolute; top:var(--p-space-3xs); left:var(--p-space-3xs); width:var(--p-size-md); height:var(--p-size-md); border-radius:var(--p-radius-circle); background:var(--p-muted); box-shadow:var(--p-knob-shadow); transition:left var(--p-duration); }
.ds .ds-choice input.ds-switch:checked::after { content:none; }
.ds .ds-switch:checked::before { left:calc(100% - var(--p-size-md) - var(--p-space-3xs)); background:var(--p-on-accent); }
.ds .ds-switch:disabled::before { background:var(--p-muted); box-shadow:none; }
@media(forced-colors:active) {
  .ds .ds-choice input:not(.ds-switch) { appearance:auto; }
  .ds .ds-choice input:not(.ds-switch)::after { display:none; }
  .ds .ds-switch { border-color:ButtonText; }
  .ds .ds-switch::before { background:ButtonText; }
  .ds .ds-switch:checked { background:Highlight; }
  .ds .ds-switch:checked::before { background:HighlightText; }
}

.ds .ds-data-table { display:grid; grid-template-columns:minmax(0,1fr); gap:var(--p-space-sm); min-width:0; width:100%; }
.ds .ds-data-table > [data-table-content] { display:grid; grid-template-columns:minmax(0,1fr); gap:var(--p-space-sm); min-width:0; }
.ds .ds-table-content { display:grid; gap:var(--p-space-sm); min-width:0; }
.ds .ds-data-table :is(th,td):first-child { width:var(--p-control-size-sm); }
.ds .ds-table-toolbar { display:flex; align-items:end; flex-wrap:wrap; gap:var(--p-space-sm); }
.ds .ds-table-toolbar > .ds-field:first-child { flex:1; min-width:calc(var(--p-space-unit) * 40); }
.ds .ds-table-toolbar > .ds-field { min-width:0; }
.ds .ds-table-scroll { overflow:auto; border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-inner-radius); }
.ds .ds-data-table table { width:100%; border-collapse:collapse; font-size:var(--p-text-body); text-align:start; }
.ds .ds-data-table th { background:var(--p-surface); font-weight:var(--p-weight-semibold); }
.ds .ds-data-table :is(th,td) { padding:var(--p-space-xs) var(--p-space-sm); border-bottom:var(--p-border-width) solid var(--p-line-subtle); text-align:start; vertical-align:middle; }
.ds .ds-data-table td:nth-child(2) { min-width:calc(var(--p-space-unit) * 40); }
.ds .ds-data-table td:nth-child(n+3) { white-space:nowrap; }
.ds .ds-data-table tr[data-selected="true"] { background:var(--p-soft); }
.ds .ds-data-table td .ds-button { justify-content:start; text-align:start; white-space:normal; height:auto; }
.ds .ds-data-table th .ds-button { white-space:nowrap; }
.ds .ds-data-table :is(th,td) .ds-button { justify-content:start; padding-inline:var(--p-space-sm); margin-inline:calc(var(--p-space-sm) * -1); }
@media(max-width:580px) { .ds .ds-data-table :is(th,td) { padding-inline:var(--p-space-xs); } .ds .ds-data-table :is(th,td) .ds-button { padding-inline:var(--p-space-xs); margin-inline:calc(var(--p-space-xs) * -1); } .ds .ds-data-table td:nth-child(2) { min-width:calc(var(--p-space-unit) * 24); } }
.ds .ds-table-pagination { display:flex; align-items:center; flex-wrap:wrap; gap:var(--p-space-xs); font-size:var(--p-text-body); }
.ds .ds-table-pagination > span { margin-inline-end:auto; }
.ds .ds-table-pagination label { display:flex; align-items:center; gap:var(--p-space-xs); }
.ds .ds-table-pagination select { width:auto; }
.ds .ds-table-selection { color:var(--p-muted); font-size:var(--p-text-body); }
.ds .ds-table-empty { display:grid; justify-items:center; gap:var(--p-space-sm); padding:var(--p-space-xl); }
.ds .ds-sr-only { position:absolute; width:var(--p-size-hairline); height:var(--p-size-hairline); padding:0; overflow:hidden; clip-path:inset(50%); white-space:nowrap; border:0; }

